SELECT 'd1eb15ce-eaf2-55e6-89a5-d46a6f304528', 'Nhà riêng nhiều tầng', 'Căn nhà độc lập từ hai tầng; một đơn vị WHOLE đại diện cho cả căn.', (SELECT id FROM room_types WHERE name='Nhà nguyên căn')
